#!/bin/sh
set -eu

base=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
output=$base/merged.csv

if [ "$#" -eq 0 ]; then
    set -- "$base"/exports/*.csv
fi

tmp=$(mktemp "$base/.merged.csv.tmp.XXXXXX")
trap 'rm -f -- "$tmp"' EXIT HUP INT TERM

python3 - "$tmp" "$@" <<'PY'
import csv
import os
import re
import sys

destination = sys.argv[1]
sources = sys.argv[2:]
integer_id = re.compile(r"[+-]?[0-9]+\Z")
header = None
records = {}
origins = {}

if not sources:
    sys.exit("merge: no input files")

for path in sources:
    try:
        stream = open(path, "r", encoding="utf-8-sig", newline="")
    except OSError as exc:
        sys.exit("merge: cannot open {}: {}".format(path, exc))

    with stream:
        reader = csv.reader(stream, strict=True)
        try:
            current_header = next(reader)
        except StopIteration:
            sys.exit("merge: {} is empty".format(path))
        except csv.Error as exc:
            sys.exit("merge: invalid CSV header in {}: {}".format(path, exc))

        if header is None:
            header = current_header
            if not header or header[0] != "transaction_id":
                sys.exit("merge: {}: first column must be transaction_id".format(path))
        elif current_header != header:
            sys.exit(
                "merge: header mismatch in {}: expected {!r}, got {!r}".format(
                    path, header, current_header
                )
            )

        try:
            for line_number, row in enumerate(reader, 2):
                if not row:
                    sys.exit("merge: {}:{}: blank record".format(path, line_number))
                if len(row) != len(header):
                    sys.exit(
                        "merge: {}:{}: expected {} fields, got {}".format(
                            path, line_number, len(header), len(row)
                        )
                    )

                raw_id = row[0]
                if not integer_id.fullmatch(raw_id):
                    sys.exit(
                        "merge: {}:{}: transaction_id {!r} is not an integer".format(
                            path, line_number, raw_id
                        )
                    )
                transaction_id = int(raw_id, 10)
                data = tuple(row[1:])

                if transaction_id in records:
                    if records[transaction_id][1:] != list(data):
                        old_path, old_line, old_row = origins[transaction_id]
                        sys.exit(
                            "merge: conflicting duplicate transaction_id {}: "
                            "{}:{} has {!r}; {}:{} has {!r}".format(
                                transaction_id,
                                old_path,
                                old_line,
                                old_row,
                                path,
                                line_number,
                                row,
                            )
                        )
                    continue

                records[transaction_id] = row
                origins[transaction_id] = (path, line_number, row)
        except csv.Error as exc:
            sys.exit("merge: invalid CSV in {} near line {}: {}".format(path, reader.line_num, exc))

try:
    with open(destination, "w", encoding="utf-8", newline="") as stream:
        writer = csv.writer(stream, lineterminator="\n")
        writer.writerow(header)
        for transaction_id in sorted(records):
            writer.writerow(records[transaction_id])
        stream.flush()
        os.fsync(stream.fileno())
except OSError as exc:
    sys.exit("merge: cannot create candidate output: {}".format(exc))
PY

if [ -e "$output" ]; then
    chmod --reference="$output" "$tmp"
else
    chmod 0644 "$tmp"
fi
mv -f -- "$tmp" "$output"
trap - EXIT HUP INT TERM
ANTRIEB_MERGE_EOF
chmod 0755 bin/merge
sh -n bin/merge && stat -c '%n mode=%a size=%s' bin/merge bin/merge.bak

